/* 3mm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "3mm.h"

/* ------------------------------------------------------------------------
 * Tunable blocking factors for the inner (column) loops of the three
 * matrix multiplications.
 *
 * They are intentionally small and can be overridden at compile time,
 * e.g.:
 *   gcc -O3 -DNDEBUG -DTILE_COL_E=128 -DTILE_COL_F=128 -DTILE_COL_G=128 ...
 *
 * Only the column dimension is blocked; each tile is processed with
 * unit-stride accesses to maximize cache reuse and vectorization.
 * --------------------------------------------------------------------- */
#ifndef TILE_COL_E
# define TILE_COL_E 64
#endif

#ifndef TILE_COL_F
# define TILE_COL_F 64
#endif

#ifndef TILE_COL_G
# define TILE_COL_G 64
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_3mm [[gnu::flatten, gnu::noinline]] (int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k, jj;

#pragma scop
  /*
   * Optimized kernel:
   *
   *  - Loop order is changed from (i,j,k) to (i,k,j) so that, for each
   *    fixed row i and inner dimension index k, we stream contiguous
   *    rows of B, D, and F along j.
   *
   *  - We use row pointers (e.g., E_row, B_row) to help the compiler
   *    generate tight, vectorizable inner loops with unit-stride
   *    accesses.
   *
   *  - A light-weight column blocking (TILE_COL_*) is applied to the
   *    innermost dimension to improve cache locality for large
   *    problem sizes. The blocking does not change the order of
   *    operations for any single output element, so floating-point
   *    results remain bit-identical to the original code.
   */

  /* E := A*B */
  for (i = 0; i < _PB_NI; i++)
  {
    DATA_TYPE *E_row       = E[i];
    const DATA_TYPE *A_row = A[i];

    /* Initialize row i of E. */
    for (j = 0; j < _PB_NJ; j++)
      E_row[j] = SCALAR_VAL(0.0);

    /* Accumulate contributions from each k into row i. */
    for (k = 0; k < _PB_NK; ++k)
    {
      const DATA_TYPE a_ik       = A_row[k];
      const DATA_TYPE *B_row_k   = B[k];

      /* Column-blocked, unit-stride update of E_row. */
      for (jj = 0; jj < _PB_NJ; jj += TILE_COL_E)
      {
        int j_end = jj + TILE_COL_E;
        if (j_end > _PB_NJ)
          j_end = _PB_NJ;

        for (j = jj; j < j_end; ++j)
          E_row[j] += a_ik * B_row_k[j];
      }
    }
  }

  /* F := C*D */
  for (i = 0; i < _PB_NJ; i++)
  {
    DATA_TYPE *F_row_i     = F[i];
    const DATA_TYPE *C_row = C[i];

    /* Initialize row i of F. */
    for (j = 0; j < _PB_NL; j++)
      F_row_i[j] = SCALAR_VAL(0.0);

    /* Accumulate contributions from each k into row i. */
    for (k = 0; k < _PB_NM; ++k)
    {
      const DATA_TYPE c_ik       = C_row[k];
      const DATA_TYPE *D_row_k   = D[k];

      for (jj = 0; jj < _PB_NL; jj += TILE_COL_F)
      {
        int j_end = jj + TILE_COL_F;
        if (j_end > _PB_NL)
          j_end = _PB_NL;

        for (j = jj; j < j_end; ++j)
          F_row_i[j] += c_ik * D_row_k[j];
      }
    }
  }

  /* G := E*F */
  for (i = 0; i < _PB_NI; i++)
  {
    DATA_TYPE *G_row       = G[i];
    const DATA_TYPE *E_row = E[i];

    /* Initialize row i of G. */
    for (j = 0; j < _PB_NL; j++)
      G_row[j] = SCALAR_VAL(0.0);

    /* Accumulate contributions from each k into row i. */
    for (k = 0; k < _PB_NJ; ++k)
    {
      const DATA_TYPE e_ik       = E_row[k];
      const DATA_TYPE *F_row_k   = F[k];

      for (jj = 0; jj < _PB_NL; jj += TILE_COL_G)
      {
        int j_end = jj + TILE_COL_G;
        if (j_end > _PB_NL)
          j_end = _PB_NL;

        for (j = jj; j < j_end; ++j)
          G_row[j] += e_ik * F_row_k[j];
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_3mm (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(E),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(F),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D),
	      POLYBENCH_ARRAY(G));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(G)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(E);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(F);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);
  POLYBENCH_FREE_ARRAY(G);

  return 0;
}
