 * These can be overridden at compile time, e.g.:
 *   gcc -O3 -DTILE_I=64 -DTILE_J=64 -DTILE_K=32 ...
 *
 * They are used to improve cache locality by operating on small
 * sub-blocks that fit into L1/L2 caches.
 * ------------------------------------------------------------------- */
#ifndef TILE_I
# define TILE_I 32
#endif

#ifndef TILE_J
# define TILE_J 32
#endif

#ifndef TILE_K
# define TILE_K 32
#endif


