 *  - Applied cache blocking (tiling) over i, j, and k dimensions.
 *    This reduces cache misses by keeping sub-blocks of the matrices
 *    in cache while they are reused.
 *  - Introduced restrict-qualified local pointers to help the
 *    compiler with alias analysis and vectorization.
 *  - Kept the per-element accumulation order over the reduction
 *    index (k) identical to the original implementation to preserve
 *    floating-point semantics as closely as possible.
 */
static void __attribute__((flatten, noinline))
kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

  /* Local copies of the polybench loop bounds for readability and to
     ensure we use the run-time problem sizes as in the original code. */
  const int ni_ = _PB_NI;
  const int nj_ = _PB_NJ;
  const int nk_ = _PB_NK;
  const int nl_ = _PB_NL;
  const int nm_ = _PB_NM;

  /* Local restrict-qualified pointers to help the compiler reason
     about aliasing. The PolyBench allocation guarantees that these
     arrays do not overlap. */
  DATA_TYPE (* restrict E_)[NJ] = E;
  DATA_TYPE (* restrict A_)[NK] = A;
  DATA_TYPE (* restrict B_)[NJ] = B;
  DATA_TYPE (* restrict F_)[NL] = F;
  DATA_TYPE (* restrict C_)[NM] = C;
  DATA_TYPE (* restrict D_)[NL] = D;
  DATA_TYPE (* restrict G_)[NL] = G;

  const DATA_TYPE zero = SCALAR_VAL(0.0);

#pragma scop
  /* ------------------------------------------------------------------
   * E := A * B
   * Dimensions:
   *   A: ni_ x nk_
   *   B: nk_ x nj_
   *   E: ni_ x nj_
   * ----------------------------------------------------------------*/

  /* Explicitly zero E once (separate from the multiply) to preserve
     the original computation order of the k-reduction. */
  for (i = 0; i < ni_; ++i)
    for (j = 0; j < nj_; ++j)
      E_[i][j] = zero;

  /* Blocked i-k-j matrix multiplication.
     Outer loops: tiles in i, k, j.
     Inner-most loop: j, to benefit from unit-stride access along rows. */
  for (int ii = 0; ii < ni_; ii += TILE_I) {
    int i_max = ii + TILE_I;
    if (i_max > ni_) i_max = ni_;

    for (int kk = 0; kk < nk_; kk += TILE_K) {
      int k_max = kk + TILE_K;
      if (k_max > nk_) k_max = nk_;

      for (int jj = 0; jj < nj_; jj += TILE_J) {
        int j_max = jj + TILE_J;
        if (j_max > nj_) j_max = nj_;

        for (i = ii; i < i_max; ++i) {
          for (k = kk; k < k_max; ++k) {
            const DATA_TYPE a_ik = A_[i][k];

            /* Pointers into the contiguous rows of B and E for the
               current (i,k) pair and j-tile. */
            const DATA_TYPE * restrict b_ptr = &B_[k][jj];
            DATA_TYPE       * restrict e_ptr = &E_[i][jj];

            /* Inner loop over j: contiguous memory accesses for both
               e_ptr and b_ptr; no loop-carried dependencies. */
            for (j = jj; j < j_max; ++j) {
              *e_ptr += a_ik * (*b_ptr);
              ++e_ptr;
              ++b_ptr;
            }
          }
        }
      }
    }
  }

  /* ------------------------------------------------------------------
   * F := C * D
   * Dimensions:
   *   C: nj_ x nm_
   *   D: nm_ x nl_
   *   F: nj_ x nl_
   * ----------------------------------------------------------------*/

  for (i = 0; i < nj_; ++i)
    for (j = 0; j < nl_; ++j)
      F_[i][j] = zero;

  for (int ii = 0; ii < nj_; ii += TILE_I) {
    int i_max = ii + TILE_I;
    if (i_max > nj_) i_max = nj_;

    for (int kk = 0; kk < nm_; kk += TILE_K) {
      int k_max = kk + TILE_K;
      if (k_max > nm_) k_max = nm_;

      for (int jj = 0; jj < nl_; jj += TILE_J) {
        int j_max = jj + TILE_J;
        if (j_max > nl_) j_max = nl_;

        for (i = ii; i < i_max; ++i) {
          for (k = kk; k < k_max; ++k) {
            const DATA_TYPE c_ik = C_[i][k];

            const DATA_TYPE * restrict d_ptr = &D_[k][jj];
            DATA_TYPE       * restrict f_ptr = &F_[i][jj];

            for (j = jj; j < j_max; ++j) {
              *f_ptr += c_ik * (*d_ptr);
              ++f_ptr;
              ++d_ptr;
            }
          }
        }
      }
    }
  }

  /* ------------------------------------------------------------------
   * G := E * F
   * Dimensions:
   *   E: ni_ x nj_
   *   F: nj_ x nl_
   *   G: ni_ x nl_
   * ----------------------------------------------------------------*/

  for (i = 0; i < ni_; ++i)
    for (j = 0; j < nl_; ++j)
      G_[i][j] = zero;

  for (int ii = 0; ii < ni_; ii += TILE_I) {
    int i_max = ii + TILE_I;
    if (i_max > ni_) i_max = ni_;

    for (int kk = 0; kk < nj_; kk += TILE_K) {
      int k_max = kk + TILE_K;
      if (k_max > nj_) k_max = nj_;

      for (int jj = 0; jj < nl_; jj += TILE_J) {
        int j_max = jj + TILE_J;
        if (j_max > nl_) j_max = nl_;

        for (i = ii; i < i_max; ++i) {
          for (k = kk; k < k_max; ++k) {
            const DATA_TYPE e_ik = E_[i][k];

            const DATA_TYPE * restrict f_ptr = &F_[k][jj];
            DATA_TYPE       * restrict g_ptr = &G_[i][jj];

            for (j = jj; j < j_max; ++j) {
              *g_ptr += e_ik * (*f_ptr);
              ++g_ptr;
              ++f_ptr;
            }
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

