static
void kernel_3mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
#pragma scop
  const DATA_TYPE zero = SCALAR_VAL(0.0);

  /* ---------------------------------------------------------------
   * E := A * B
   *   A: (ni x nk)
   *   B: (nk x nj)
   *   E: (ni x nj)
   *
   * Blocked over i (rows of A/E), j (cols of B/E), and k (reduction).
   * Inner-most loop runs over contiguous j to improve cache locality
   * and enable efficient vectorization.
   * ------------------------------------------------------------ */
  for (int ii = 0; ii < _PB_NI; ii += TILE_I) {
    int i_end = ii + TILE_I;
    if (i_end > _PB_NI) i_end = _PB_NI;

    for (int jj = 0; jj < _PB_NJ; jj += TILE_J) {
      int j_end = jj + TILE_J;
      if (j_end > _PB_NJ) j_end = _PB_NJ;

      /* Initialize current tile of E to zero. */
      for (int i = ii; i < i_end; ++i) {
        DATA_TYPE *restrict E_row = &E[i][0];
        for (int j = jj; j < j_end; ++j) {
          E_row[j] = zero;
        }
      }

      /* Accumulate products into E tile. */
      for (int kk = 0; kk < _PB_NK; kk += TILE_K) {
        int k_end = kk + TILE_K;
        if (k_end > _PB_NK) k_end = _PB_NK;

        for (int i = ii; i < i_end; ++i) {
          DATA_TYPE *restrict       E_row = &E[i][0];
          const DATA_TYPE *restrict A_row = &A[i][0];

          for (int k = kk; k < k_end; ++k) {
            DATA_TYPE a_ik = A_row[k];
            const DATA_TYPE *restrict B_row = &B[k][0];

            /* j-loop over contiguous elements of E_row and B_row. */
#pragma GCC ivdep
            for (int j = jj; j < j_end; ++j) {
              E_row[j] += a_ik * B_row[j];
            }
          }
        }
      }
    }
  }

  /* ---------------------------------------------------------------
   * F := C * D
   *   C: (nj x nm)
   *   D: (nm x nl)
   *   F: (nj x nl)
   * Same blocked structure as for E.
   * ------------------------------------------------------------ */
  for (int ii = 0; ii < _PB_NJ; ii += TILE_I) {
    int i_end = ii + TILE_I;
    if (i_end > _PB_NJ) i_end = _PB_NJ;

    for (int jj = 0; jj < _PB_NL; jj += TILE_J) {
      int j_end = jj + TILE_J;
      if (j_end > _PB_NL) j_end = _PB_NL;

      /* Initialize current tile of F to zero. */
      for (int i = ii; i < i_end; ++i) {
        DATA_TYPE *restrict F_row = &F[i][0];
        for (int j = jj; j < j_end; ++j) {
          F_row[j] = zero;
        }
      }

      /* Accumulate products into F tile. */
      for (int kk = 0; kk < _PB_NM; kk += TILE_K) {
        int k_end = kk + TILE_K;
        if (k_end > _PB_NM) k_end = _PB_NM;

        for (int i = ii; i < i_end; ++i) {
          DATA_TYPE *restrict       F_row = &F[i][0];
          const DATA_TYPE *restrict C_row = &C[i][0];

          for (int k = kk; k < k_end; ++k) {
            DATA_TYPE c_ik = C_row[k];
            const DATA_TYPE *restrict D_row = &D[k][0];

