  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_3mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

  /* Create restrict-qualified aliases for better alias analysis and
     to enable more aggressive vectorization. Dimensions are taken from
     the runtime parameters (VLAs). */
  DATA_TYPE (* restrict E_)[nj] = E;
  DATA_TYPE (* restrict A_)[nk] = A;
  DATA_TYPE (* restrict B_)[nj] = B;
  DATA_TYPE (* restrict F_)[nl] = F;
  DATA_TYPE (* restrict C_)[nm] = C;
  DATA_TYPE (* restrict D_)[nl] = D;
  DATA_TYPE (* restrict G_)[nl] = G;

#pragma scop
  /* -----------------------------------------------------------------------
   * Zero-initialize result matrices.
   * The original code initialized each element just before accumulating
   * into it. Here we separate initialization from accumulation; every
   * element is still set to zero exactly once before any update.
   * ---------------------------------------------------------------------*/
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      E_[i][j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_NJ; i++)
    for (j = 0; j < _PB_NL; j++)
      F_[i][j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      G_[i][j] = SCALAR_VAL(0.0);

  /* -----------------------------------------------------------------------
   * Blocked matrix multiplication: E := A * B
   *
   * Original:
   *   for i
   *     for j
   *       E[i][j] = 0;
   *       for k
   *         E[i][j] += A[i][k] * B[k][j];
   *
   * New version:
   *   - Uses i/k/j blocking to improve cache locality.
   *   - Keeps j as the innermost index to access contiguous memory
   *     in E and B, enabling efficient vectorization.
   *   - Each (i,j,k) contribution A[i][k] * B[k][j] is accumulated
   *     into E[i][j] exactly once, as in the original code.
   * ---------------------------------------------------------------------*/
  for (int ii = 0; ii < _PB_NI; ii += T1_I) {
    const int i_max = (ii + T1_I < _PB_NI) ? (ii + T1_I) : _PB_NI;

    for (int kk = 0; kk < _PB_NK; kk += T1_K) {
      const int k_max = (kk + T1_K < _PB_NK) ? (kk + T1_K) : _PB_NK;

      for (int jj = 0; jj < _PB_NJ; jj += T1_J) {
        const int j_max = (jj + T1_J < _PB_NJ) ? (jj + T1_J) : _PB_NJ;
        const int len   = j_max - jj; /* number of columns in this tile */

        for (i = ii; i < i_max; ++i) {
          for (k = kk; k < k_max; ++k) {
            const DATA_TYPE a_ik = A_[i][k];

            /* Pointers to the start of the current row segments. */
            DATA_TYPE * restrict e_row = &E_[i][jj];
            const DATA_TYPE * restrict b_row = &B_[k][jj];

#pragma GCC ivdep
            for (int t = 0; t < len; ++t) {
              e_row[t] += a_ik * b_row[t];
            }
          }
        }
      }
    }
  }

  /* -----------------------------------------------------------------------
   * Blocked matrix multiplication: F := C * D
   *
   * Shapes:
   *   C: NJ x NM
   *   D: NM x NL
   *   F: NJ x NL
   * Same strategy as for E := A * B.
   * ---------------------------------------------------------------------*/
  for (int ii = 0; ii < _PB_NJ; ii += T2_I) {
    const int i_max = (ii + T2_I < _PB_NJ) ? (ii + T2_I) : _PB_NJ;

    for (int kk = 0; kk < _PB_NM; kk += T2_K) {
      const int k_max = (kk + T2_K < _PB_NM) ? (kk + T2_K) : _PB_NM;

      for (int jj = 0; jj < _PB_NL; jj += T2_J) {
        const int j_max = (jj + T2_J < _PB_NL) ? (jj + T2_J) : _PB_NL;
        const int len   = j_max - jj;

        for (i = ii; i < i_max; ++i) {
          for (k = kk; k < k_max; ++k) {
            const DATA_TYPE c_ik = C_[i][k];

            DATA_TYPE * restrict f_row = &F_[i][jj];
            const DATA_TYPE * restrict d_row = &D_[k][jj];

#pragma GCC ivdep
            for (int t = 0; t < len; ++t) {
              f_row[t] += c_ik * d_row[t];
            }
          }
        }
      }
    }
  }

  /* -----------------------------------------------------------------------
   * Blocked matrix multiplication: G := E * F
   *
   * Shapes:
   *   E: NI x NJ
   *   F: NJ x NL
   *   G: NI x NL
   * Again we use i/k/j blocking with j innermost.
   * ---------------------------------------------------------------------*/
  for (int ii = 0; ii < _PB_NI; ii += T3_I) {
    const int i_max = (ii + T3_I < _PB_NI) ? (ii + T3_I) : _PB_NI;

    for (int kk = 0; kk < _PB_NJ; kk += T3_K) {
      const int k_max = (kk + T3_K < _PB_NJ) ? (kk + T3_K) : _PB_NJ;

      for (int jj = 0; jj < _PB_NL; jj += T3_J) {
        const int j_max = (jj + T3_J < _PB_NL) ? (jj + T3_J) : _PB_NL;
        const int len   = j_max - jj;

        for (i = ii; i < i_max; ++i) {
          for (k = kk; k < k_max; ++k) {
            const DATA_TYPE e_ik = E_[i][k];

            DATA_TYPE * restrict g_row = &G_[i][jj];
            const DATA_TYPE * restrict f_row = &F_[k][jj];

#pragma GCC ivdep
            for (int t = 0; t < len; ++t) {
              g_row[t] += e_ik * f_row[t];
            }
          }
        }
      }
    }
  }
#pragma endscop

}


